                let mut j = i + 1;
                let mut end = None;
                while j < tokens.len() {
                    if tokens[j] == ";" {
                        end = Some(j);
                        break;
                    }
                    j += 1;
                }
                let end = end.ok_or(Error::InvalidWord)?;
                if end == i + 1 {
