        Forth {
            stack: Vec::new(),
            dict: HashMap::new(),
        }
    }

    pub fn stack(&self) -> &[Value] {
        &self.stack
    }

    fn resolve(&self, token: &str) -> Option<Op> {
        let lower = token.to_lowercase();
        if let Some(body) = self.dict.get(&lower) {
            return Some(Op::Custom(Rc::clone(body)));
        }
        let builtin = match lower.as_str() {
            "+" => Builtin::Add,
            "-" => Builtin::Sub,
            "*" => Builtin::Mul,
            "/" => Builtin::Div,
            "dup" => Builtin::Dup,
            "drop" => Builtin::Drop,
            "swap" => Builtin::Swap,
            "over" => Builtin::Over,
            _ => return None,
        };
        Some(Op::Builtin(builtin))
    }

    fn exec_op(&mut self, op: &Op) -> Result {
        match op {
            Op::Push(v) => {
                self.stack.push(*v);
                Ok(())
            }
            Op::Builtin(b) => self.exec_builtin(*b),
            Op::Custom(body) => {
                for inner in body.iter() {
                    self.exec_op(inner)?;
                }
                Ok(())
            }
        }
    }

    fn exec_builtin(&mut self, b: Builtin) -> Result {
        match b {
            Builtin::Add => {
                let y = self.stack.pop().ok_or(Error::StackUnderflow)?;
                let x = self.stack.pop().ok_or(Error::StackUnderflow)?;
                self.stack.push(x + y);
                Ok(())
            }
            Builtin::Sub => {
                let y = self.stack.pop().ok_or(Error::StackUnderflow)?;
                let x = self.stack.pop().ok_or(Error::StackUnderflow)?;
                self.stack.push(x - y);
                Ok(())
            }
            Builtin::Mul => {
                let y = self.stack.pop().ok_or(Error::StackUnderflow)?;
                let x = self.stack.pop().ok_or(Error::StackUnderflow)?;
                self.stack.push(x * y);
                Ok(())
            }
            Builtin::Div => {
                let y = self.stack.pop().ok_or(Error::StackUnderflow)?;
                let x = self.stack.pop().ok_or(Error::StackUnderflow)?;
                if y == 0 {
                    return Err(Error::DivisionByZero);
                }
                self.stack.push(x / y);
                Ok(())
            }
            Builtin::Dup => {
                let x = *self.stack.last().ok_or(Error::StackUnderflow)?;
                self.stack.push(x);
                Ok(())
            }
            Builtin::Drop => {
                self.stack.pop().ok_or(Error::StackUnderflow)?;
                Ok(())
            }
            Builtin::Swap => {
                let len = self.stack.len();
                if len < 2 {
                    return Err(Error::StackUnderflow);
                }
                self.stack.swap(len - 1, len - 2);
                Ok(())
            }
            Builtin::Over => {
                let len = self.stack.len();
                if len < 2 {
                    return Err(Error::StackUnderflow);
                }
                let x = self.stack[len - 2];
                self.stack.push(x);
                Ok(())
            }
        }
    }

    pub fn eval(&mut self, input: &str) -> Result {
        let tokens: Vec<&str> = input.split_whitespace().collect();
        let mut i = 0;
        while i < tokens.len() {
            let token = tokens[i];
            if token == ":" {
                // find matching ";"
                let mut j = i + 1;
                let mut end = None;
                while j < tokens.len() {
                    if tokens[j] == ";" {
                        end = Some(j);
                        break;
                    }
                    j += 1;
                }
                let end = end.ok_or(Error::InvalidWord)?;
                if end == i + 1 {
                    // no name
                    return Err(Error::InvalidWord);
                }
                let name = tokens[i + 1];
                if is_number(name) {
                    return Err(Error::InvalidWord);
                }
                let name_lower = name.to_lowercase();
                let mut body: Vec<Op> = Vec::new();
                for k in (i + 2)..end {
                    let t = tokens[k];
                    let op = if is_number(t) {
                        let v: Value = t.parse().map_err(|_| Error::InvalidWord)?;
                        Op::Push(v)
                    } else {
                        self.resolve(t).ok_or(Error::UnknownWord)?
                    };
                    body.push(op);
                }
                self.dict.insert(name_lower, Rc::new(body));
                i = end + 1;
            } else {
                let op = if is_number(token) {
                    let v: Value = token.parse().map_err(|_| Error::InvalidWord)?;
                    Op::Push(v)
                } else {
                    self.resolve(token).ok_or(Error::UnknownWord)?
                };
                self.exec_op(&op)?;
                i += 1;
            }
        }
        Ok(())
    }
}

